// rc_logic.c - generated by split_c.py from RayCaster.c
#include "rc_priv.h"



bool rc_IsBossLevel(uint16_t lv)                // the Dragon round
{
    return (rc_lv.boss != 0u) && (lv == rc_level);
}


// Level-up: how much XP the next level needs.
uint16_t rc_XpNeed(void)
{
    return (uint16_t)(24u + 12u * rc_xpLv);
}


static void GainXp(uint16_t amt)
{
    uint16_t need;

    rc_xp += amt;
    for(;;)
    {
        need = rc_XpNeed();
        if(rc_xp < need) break;
        rc_xp -= need;
        rc_xpLv++;
        rc_lvPending++;
    }
    rc_hud |= HUD_XP | HUD_LEVEL;
}


//-----------------------------------------------------------------------------
// Equipment slots
//-----------------------------------------------------------------------------
static bool SlotOwned(uint16_t slot)
{
    if(slot < NUM_STAFF) return (rc_staffOwned & (1u << slot)) != 0;
    return (rc_itemOwned & (1u << (slot - NUM_STAFF))) != 0;
}


const char *rc_SlotName(uint16_t slot)
{
    return (slot < NUM_STAFF) ? rc_kStaff[slot].name : rc_kItem[slot - NUM_STAFF].name;
}


uint32_t rc_SlotColor(uint16_t slot)
{
    return (slot < NUM_STAFF) ? rc_kStaff[slot].color : rc_kItem[slot - NUM_STAFF].color;
}


uint16_t rc_SlotMana(uint16_t slot)
{
    return (slot < NUM_STAFF) ? rc_kStaffMana[slot] : rc_kItemMana[slot - NUM_STAFF];
}


static void DropMana(int16_t x, int16_t y);


static uint16_t StaffCooldown(uint16_t st)
{
    int16_t cd = (int16_t)((rc_kStaff[st].cooldown * (100 - 9 * rc_lvRate)) / 100);

    if(rc_haste) cd >>= 1;
    return (cd < 4) ? 4 : (uint16_t)cd;
}


void rc_CycleEquip(void)
{
    uint16_t i, slot = rc_equip;

    for(i = 1; i < NUM_SLOT; i++)
    {
        slot = (slot + 1u) % NUM_SLOT;
        if(SlotOwned(slot)) break;
    }

    if(slot != rc_equip && SlotOwned(slot))
    {
        rc_equip = slot;
        rc_hud  |= HUD_STAFF;
        rc_viewDirty = 2;                // redraw the new item in the hand
        rc_Sfx(&sfx_menu_move);
    }
}


//-----------------------------------------------------------------------------
// Player damage / enemy damage
//-----------------------------------------------------------------------------
static uint16_t s_fragCount;

void rc_HurtPlayer(void)
{
    uint16_t dmg = 1;

    if(rc_invuln || rc_hp == 0 || rc_aegis) return;

    if(rc_curses & CU_GLASS)        dmg = 2;                        // Glass Body: you take double damage
    else if((rc_curses & CU_FRAGILE) && ((++s_fragCount) & 3u) == 0u) dmg = 2;   // Fragile: every 4th hit is heavy
    if(dmg > rc_hp) dmg = rc_hp;
    rc_hp = (uint16_t)(rc_hp - dmg);
    rc_invuln = (rc_traits & (1u << TR_THICK)) ? RC_THICK_FRAMES : RC_INVULN_FRAMES;
    rc_hud   |= HUD_HEARTS;
    rc_viewDirty = 2;

    if(rc_hp == 0) rc_EnterOver();
    else          rc_Sfx(&sfx_hit);
}


static void KillEnemy(Enemy *e)
{
    const EnemyDef *d = &rc_kEnemy[e->type];
    uint16_t i, g, xp;
    bool     mini = RC_IS_MINI(e->type);
    int16_t  ex = e->x, ey = e->y;

    e->alive = 0;
    if(rc_alive) rc_alive--;

    if(e->sum)                                  // summoned minions: tiny reward
    {
        g  = 2;
        xp = 1;
    }
    else
    {
        g  = (uint16_t)(((uint32_t)d->gold * (100u + 20u * rc_lvGold)) / 100u);
        xp = (uint16_t)(d->xp + rc_level / 4u);
    }
    if(rc_curses & CU_GREED) g = (uint16_t)((g + 1u) >> 1);            // Greed curse: half the gold
    rc_gold += g;
    rc_kills++;
    rc_hud |= HUD_GOLD | HUD_LEFT;
    GainXp(xp);
    if((rc_traits & (1u << TR_VAMP)) && (rc_kills % 10u) == 0 && rc_hp < rc_maxHp)
    {
        rc_hp++;
        rc_hud |= HUD_HEARTS;
    }
    rc_Sfx(&sfx_explosion);

    if(!e->sum && (mini || e->type == ET_DRAGON || (Rand16() % 100u) < MANA_DROP_PCT))
        DropMana(ex, ey);

    if(e->type == ET_SLIME)                     // splits into two smaller slimes
    {
        for(i = 0; i < 2; i++)
        {
            Enemy *s2 = rc_SpawnEnemy(ET_SLIME_S, (int16_t)(ex + (i ? 330 : -330)), ey);
            if(s2 != NULL && Blocked(s2->x, s2->y, 230)) { s2->x = ex; s2->y = ey; }
        }
    }
    else if(e->type == ET_IMP)
        rc_Explode(ex, ey);

    if(mini)                                    // guaranteed rewards, and the Dragon gets closer
    {
        if(rc_hp < rc_maxHp) { rc_hp++; rc_hud |= HUD_HEARTS; }
        if(rc_miniAlive) rc_miniAlive--;
        rc_miniKills++;
        rc_hud |= HUD_LEFT;
    }

    if(mini && rc_miniAlive == 0u && rc_denState != DEN_FIGHT) rc_ApplyTheme(TH_BASEMENT);

    if(mini || e->type == ET_NECRO)             // their summoned minions vanish with them
    {
        for(i = 0; i < RC_MAX_ENEMIES; i++)
            if(rc_en[i].alive && rc_en[i].sum)
            {
                rc_en[i].alive = 0;
                if(rc_alive) rc_alive--;
            }
    }

    if(e->type == ET_DRAGON)
    {
        rc_bossAlive = 0;
        rc_miniKills = 0;                       // three more mini-bosses wake it again
        rc_dragonKills++;
        for(i = 0; i < RC_MAX_ENEMIES; i++)     // minions die with their master
            rc_en[i].alive = 0;
        rc_alive = 0;
    }
}


// quiet = damage-over-time / splash tick: no knockback, no frost, no blip.
void rc_HealEnemy(Enemy *e, int16_t amt)
{
    e->hp = (int16_t)(e->hp + amt);
    if(e->hp > e->mhp) e->hp = e->mhp;
    rc_hud |= HUD_LEFT;
}


void rc_DamageEnemyEx(Enemy *e, uint16_t dmg, int16_t c, int16_t s, bool quiet)
{
    if(e->type == ET_GHOST && e->st == 1) return;                       // intangible
    if(!quiet && (rc_curses & CU_GLASS)) dmg = (uint16_t)(dmg * 2u);   // Glass Body: you deal double damage
    if(e->type == ET_HOBGOB && e->st != 3 && dmg > 1u) dmg--;           // shield (down while recovering)
    if(e->type == ET_GOLEM)
    {
        if(e->st == 5)      dmg = (uint16_t)((dmg + 1u) >> 1);          // Fortification
        else if(e->st == 4) dmg = (uint16_t)(dmg * 2u);                 // weak point exposed
    }
    e->hp   -= (int16_t)dmg;
    e->flash = 3;
    rc_hud   |= HUD_LEFT;

    if(e->hp <= 0)
    {
        KillEnemy(e);
        return;
    }

    if(quiet) return;

    if((rc_traits & (1u << TR_KNOCK)) && !RC_IS_MINI(e->type) && e->type != ET_DRAGON)
    {
        int16_t nx = e->x + (int16_t)(((int32_t)c * 260L) >> 14);
        int16_t ny = e->y + (int16_t)(((int32_t)s * 260L) >> 14);

        if(!Blocked(nx, e->y, 220)) e->x = nx;
        if(!Blocked(e->x, ny, 220)) e->y = ny;
    }

    if(rc_traits & (1u << TR_FROST)) e->slow = 90;

    rc_SfxSoft(&sfx_blip);
}


static void DamageEnemy(Enemy *e, uint16_t dmg, int16_t c, int16_t s)
{
    rc_DamageEnemyEx(e, dmg, c, s, false);
}


// Damage scaled by the Damage stat: base * (4 + level) / 4.
static uint16_t ScaledDmg(uint16_t base)
{
    uint16_t d = (uint16_t)((base * (4u + rc_lvDmg) + 2u) >> 2);
    return (d < 1u) ? 1u : d;
}


//-----------------------------------------------------------------------------
// Objects (flasks in flight, clouds, sparks, enemy laser bolts)
//-----------------------------------------------------------------------------
Obj *rc_NewObj(uint16_t kind)
{
    uint16_t i, pick = 0xFFFFu, oldest = 0;
    Obj     *o;

    for(i = 0; i < RC_MAX_OBJ; i++)
        if(!rc_obj[i].alive) { pick = i; break; }

    if(pick == 0xFFFFu)                         // full: recycle a spark or the oldest cloud
    {
        for(i = 0; i < RC_MAX_OBJ; i++)
        {
            if(rc_obj[i].kind != OB_SPARK && rc_obj[i].kind != OB_CLOUD && rc_obj[i].kind != OB_AREA) continue;
            if(pick == 0xFFFFu || rc_obj[i].kind == OB_SPARK ||
               rc_obj[i].age > oldest)
            {
                pick   = i;
                oldest = rc_obj[i].age;
                if(rc_obj[i].kind == OB_SPARK) break;
            }
        }
        if(pick == 0xFFFFu) return NULL;
    }

    o = &rc_obj[pick];
    o->x = o->y = o->vx = o->vy = o->z = o->r = 0;
    o->kind = kind;
    o->pal  = 0;
    o->sc   = 0;
    o->life = 0;
    o->age  = 0;
    o->aux  = 0;
    o->alive = 1;
    return o;
}


static void DropMana(int16_t x, int16_t y)
{
    Obj *o = rc_NewObj(OB_MANA);

    if(o == NULL) return;                       // object list full: no bottle this time
    o->x    = x;
    o->y    = y;
    o->z    = 0;
    o->pal  = PT_FLASK_MANA;
    o->life = MANA_BOTTLE_LIFE;
}


void rc_AddSpark(int16_t x, int16_t y, int16_t z, uint16_t sc, uint16_t pal, uint16_t life)
{
    Obj *o = rc_NewObj(OB_SPARK);

    if(o == NULL) return;
    o->x = x;  o->y = y;  o->z = z;
    o->sc = sc;  o->pal = pal;  o->life = life;
}


// A flask breaks: splash everything near, leave a puff (venom: a lingering cloud).
static void Shatter(Obj *o)
{
    uint16_t kind = o->aux;
    int16_t  rad  = rc_kPotRadius[kind];
    uint16_t dmg  = ScaledDmg(rc_kPotDmg[kind]);
    uint16_t i;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        Enemy *e = &rc_en[i];

        if(!e->alive) continue;
        if(Dist10(e->x - o->x, e->y - o->y) >= rad + (rc_kEnemy[e->type].radius >> 1))
            continue;

        rc_DamageEnemyEx(e, dmg, 0, 0, true);
        if(!e->alive) continue;

        if(kind == PK_FIRE)       e->burn = 90;
        else if(kind == PK_FROST) { e->freeze = 40; e->slow = 220; }
        else                      e->slow = 60;
    }

    o->kind = OB_CLOUD;                         // the flask becomes its own splash cloud
    o->age  = 0;
    o->life = rc_kPotLife[kind];
    o->sc   = rc_kPotScale[kind];
    o->pal  = PT_PUFF_FIRE + kind;
    o->z    = 0;
    o->vx   = o->vy = 0;
    rc_Sfx(&sfx_explosion);
}


void rc_UpdateObjects(void)
{
    uint16_t i, j;
    int16_t  nx, ny;

    for(i = 0; i < RC_MAX_OBJ; i++)
    {
        Obj *o = &rc_obj[i];

        if(!o->alive) continue;

        switch(o->kind)
        {
            case OB_FLASK:
                o->age++;
                nx = o->x + o->vx;
                ny = o->y + o->vy;
                if(Blocked(nx, ny, 60)) { Shatter(o); break; }
                o->x = nx;
                o->y = ny;
                o->z = (int16_t)(9 - (int16_t)((o->age * 7u) / o->life));
                for(j = 0; j < RC_MAX_ENEMIES; j++)
                {
                    if(!rc_en[j].alive) continue;
                    if(Dist10(rc_en[j].x - o->x, rc_en[j].y - o->y) <
                       rc_kEnemy[rc_en[j].type].radius + 150)
                    {
                        Shatter(o);
                        break;
                    }
                }
                if(o->kind == OB_FLASK && o->age >= o->life) Shatter(o);
                break;

            case OB_BOLT:                       // enemy projectile: dodge it
                nx = o->x + o->vx;
                ny = o->y + o->vy;
                if(Blocked(nx, ny, 80))
                {
                    if(o->aux == BK_WEB)                    // a web that hits the floor leaves a sticky patch
                    {
                        o->kind = OB_AREA;
                        o->aux  = AR_WEB;
                        o->r    = 450;
                        o->age  = 0;
                        o->life = 140;
                    }
                    else o->alive = 0;
                    break;
                }
                o->x = nx;
                o->y = ny;
                if(Dist10(rc_px - o->x, rc_py - o->y) < ((o->aux == BK_FLAME) ? 360 : 300))
                {
                    o->alive = 0;
                    if(o->aux == BK_WEB)
                    {
                        rc_pSlow = 120;                         // webs only slow you
                        rc_hud  |= HUD_HINT;
                    }
                    else
                    {
                        bool hit = (rc_invuln == 0 && rc_hp != 0 && rc_aegis == 0);

                        if(o->aux == BK_ICE) { rc_pSlow = 100; rc_hud |= HUD_HINT; }
                        if(o->aux == BK_DRAIN && hit)           // blood drain heals the caster
                        {
                            for(j = 0; j < RC_MAX_ENEMIES; j++)
                                if(rc_en[j].alive && (rc_en[j].type == ET_VAMPIRE || rc_en[j].type == ET_LICH))
                                    rc_HealEnemy(&rc_en[j], 10);
                        }
                        rc_HurtPlayer();               // (does nothing during invulnerability / Aegis)
                    }
                    break;
                }
                if(++o->age >= o->life) o->alive = 0;
                break;

            case OB_WARN:                       // red ring, then the hazard appears
                if(++o->age >= o->life)
                {
                    if(o->vx)                   // vx = how long the hazard lasts (0 = ring only)
                    {
                        o->kind = OB_AREA;
                        o->life = (uint16_t)o->vx;
                        o->age  = 0;
                        o->vx   = 0;
                        if(o->aux == AR_BLAST) rc_Sfx(&sfx_explosion);
                    }
                    else o->alive = 0;
                }
                break;

            case OB_AREA:                       // floor hazard: hurts or slows while you stand in it
                if(++o->age >= o->life) { o->alive = 0; break; }
                if(Dist10(rc_px - o->x, rc_py - o->y) < o->r)
                {
                    if(o->aux == AR_WEB)
                    {
                        if(rc_pSlow < 20u) { rc_pSlow = 20; rc_hud |= HUD_HINT; }
                    }
                    else if((o->age % 12u) == 0) rc_HurtPlayer();
                }
                break;

            case OB_WAVE:                       // expanding ring: hurts once when it crosses you
                o->r = (int16_t)(o->r + o->vx);
                if(o->r >= o->vy) { o->alive = 0; break; }
                if(!o->sc && Abs16((int16_t)(Dist10(rc_px - o->x, rc_py - o->y) - o->r)) < 260)
                {
                    o->sc = 1;
                    rc_HurtPlayer();
                    if(o->aux == WV_ICE) { rc_pSlow = 100; rc_hud |= HUD_HINT; }
                }
                break;

            case OB_CHEST:                      // walk into it: what is inside depends on the kind
                if(Dist10(rc_px - o->x, rc_py - o->y) < 750)
                {
                    o->alive = 0;
                    rc_chestTimer = 0;
                    rc_AddSpark(o->x, o->y, 4, 14, PT_PUFF_ARCANE, 10);
                    if(o->aux == CH_POISON)             // trap: poison cloud, a little gold
                    {
                        Obj *a2 = rc_NewObj(OB_AREA);

                        if(a2 != NULL) { a2->x = o->x; a2->y = o->y; a2->r = 1100; a2->life = 200; a2->aux = AR_SLIME; }
                        rc_gold += 20u;
                        rc_Sfx(&sfx_explosion);
                    }
                    else
                    {
                        rc_gold += (uint16_t)((o->aux == CH_CURSED ? 100u : 50u) + (o->aux == CH_CURSED ? 20u : 12u) * rc_level);
                        if(rc_hp < rc_maxHp) { rc_hp++; rc_hud |= HUD_HEARTS; }
                        DropMana(o->x, o->y);
                        if(o->aux == CH_CURSED)         // big reward, but a curse comes with it
                        {
                            uint16_t tries, bit;

                            for(tries = 0; tries < 8u; tries++)
                            {
                                bit = (uint16_t)(1u << (Rand16() & 3u));
                                if(!(rc_curses & bit)) { rc_curses |= bit; break; }
                            }
                            rc_Sfx(&sfx_game_over);
                        }
                        else rc_Sfx(&sfx_coin);
                    }
                    rc_hud |= HUD_GOLD;
                }
                break;

            case OB_MERCHANT:                   // stands in his alcove; the stick button opens the shop
                break;


            case OB_CLOUD:
                if(++o->age >= o->life) { o->alive = 0; break; }
                if(o->aux == PK_VENOM && (o->age % 12u) == 0)
                {
                    for(j = 0; j < RC_MAX_ENEMIES; j++)
                    {
                        Enemy *e = &rc_en[j];

                        if(!e->alive) continue;
                        if(Dist10(e->x - o->x, e->y - o->y) >=
                           rc_kPotRadius[PK_VENOM] + (rc_kEnemy[e->type].radius >> 1))
                            continue;
                        rc_DamageEnemyEx(e, (uint16_t)(1u + rc_lvDmg / 3u), 0, 0, true);
                        if(e->alive) e->slow = 30;
                    }
                }
                break;

            case OB_MANA:                       // mana bottle on the floor
                if(++o->age >= o->life) { o->alive = 0; break; }
                o->z = (int16_t)((o->age >> 3) & 1u);                   // little bob
                if(rc_mana < MANA_MAX &&
                   Dist10(rc_px - o->x, rc_py - o->y) < MANA_PICKUP_R)
                {
                    rc_mana += MANA_BOTTLE;
                    if(rc_mana > MANA_MAX) rc_mana = MANA_MAX;
                    o->alive = 0;
                    rc_Sfx(&sfx_powerup);
                }
                break;

            default:                            // OB_SPARK
                if(++o->age >= o->life) o->alive = 0;
                break;
        }
    }
}


//-----------------------------------------------------------------------------
// Staffs: hitscan beams
//-----------------------------------------------------------------------------
static void FireBeam(int16_t angle, uint16_t st)
{
    uint16_t tile, side;
    int16_t  c, s, best;
    int32_t  wall, bestAlong, along, perp;
    uint16_t hitMask = 0, left, i, dmg;
    int16_t  rx, ry;

    angle &= RC_ANGLE_MASK;
    wall = (int32_t)rc_RC_CastRay(angle, &tile, &side) << 2;       // Q8 -> Q10
    c = COS(angle);
    s = SIN(angle);

    left = 1u + rc_kStaff[st].pierce + ((rc_traits & (1u << TR_PIERCE)) ? 1u : 0u);

    while(left--)
    {
        best      = -1;
        bestAlong = wall;

        for(i = 0; i < RC_MAX_ENEMIES; i++)
        {
            if(!rc_en[i].alive || (hitMask & (1u << i))) continue;
            if(rc_en[i].type == ET_GHOST && rc_en[i].st == 1u) continue;     // intangible

            rx    = rc_en[i].x - rc_px;
            ry    = rc_en[i].y - rc_py;
            along = ((int32_t)rx * c + (int32_t)ry * s) >> 14;
            if(along <= 0 || along >= bestAlong) continue;

            perp = ((int32_t)ry * c - (int32_t)rx * s) >> 14;
            if(perp < 0) perp = -perp;
            if(perp > rc_kEnemy[rc_en[i].type].radius) continue;

            best      = (int16_t)i;
            bestAlong = along;
        }

        if(best < 0) break;

        hitMask |= (1u << best);

        dmg = ScaledDmg(rc_kStaff[st].dmg);
        if((rc_traits & (1u << TR_LUCKY)) && (Rand16() % 5u) == 0) dmg *= 2u;

        DamageEnemy(&rc_en[best], dmg, c, s);
    }
}


static void Fire(void)
{
    uint16_t     st = rc_equip;
    const Staff *sp = &rc_kStaff[st];
    uint16_t     i;
    int16_t      off;

    rc_cdMax[st] = StaffCooldown(st);
    rc_cd[st]    = rc_cdMax[st];
    rc_fxN       = sp->beams;
    rc_fxColor   = sp->color;

    for(i = 0; i < sp->beams; i++)
    {
        off = (int16_t)((((int16_t)(2 * i) - (int16_t)(sp->beams - 1)) * (int16_t)sp->spread) / 2);
        FireBeam(rc_ang + off, st);
        rc_fxX[i] = (int16_t)(RC_VIEW_X0 + RC_VIEW_W / 2 + off * RC_PX_PER_UNIT);
    }

    rc_fxTimer   = 4;
    rc_viewDirty = 2;
    if(rc_sfxHold == 0) Buzzer_PlaySfx(rc_kStaffSfx[st]);
    rc_stepBlock = 5;                            // footsteps never cut a shot off
}


//-----------------------------------------------------------------------------
// Magic items
//-----------------------------------------------------------------------------
static bool ThrowFlask(uint16_t kind)
{
    int16_t c = COS(rc_ang);
    int16_t s = SIN(rc_ang);
    int16_t sx, sy;
    Obj    *o = rc_NewObj(OB_FLASK);

    if(o == NULL) return false;

    sx = rc_px + (int16_t)(((int32_t)c * 300L) >> 14);
    sy = rc_py + (int16_t)(((int32_t)s * 300L) >> 14);
    if(Blocked(sx, sy, 60)) { sx = rc_px; sy = rc_py; }       // nose against a wall

    o->x    = sx;
    o->y    = sy;
    o->vx   = (int16_t)(((int32_t)c * 110L) >> 14);
    o->vy   = (int16_t)(((int32_t)s * 110L) >> 14);
    o->z    = 9;
    o->aux  = kind;
    o->life = 42;
    o->pal  = PT_FLASK_FIRE + kind;
    Buzzer_PlaySfx(&sfx_jump);
    return true;
}


// Nearest visible enemies in front of the player (arc +-90 units, line of sight).
static uint16_t AcquireTargets(uint16_t maxN, uint16_t *out)
{
    int16_t  c = COS(rc_ang);
    int16_t  s = SIN(rc_ang);
    uint16_t cand[RC_MAX_ENEMIES], candD[RC_MAX_ENEMIES];
    uint16_t nc = 0, n = 0, i, k, tile, side;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        const Enemy *e = &rc_en[i];
        int16_t rx, ry, along, sd, ratio, theta;
        uint16_t wd;

        if(!e->alive) continue;
        if(e->type == ET_GHOST && e->st == 1u) continue;
        rx    = e->x - rc_px;
        ry    = e->y - rc_py;
        along = (int16_t)(((int32_t)rx * c + (int32_t)ry * s) >> 14);
        if(along < 200) continue;

        sd    = (int16_t)(((int32_t)ry * c - (int32_t)rx * s) >> 14);
        ratio = (int16_t)(((int32_t)sd * 256L) / along);
        theta = (ratio < 0) ? -ratio : ratio;
        if(theta > 256) continue;
        theta = rc_atan[theta];
        if(theta > 90) continue;
        if(ratio < 0) theta = -theta;

        wd = rc_RC_CastRay(rc_ang + theta, &tile, &side);           // Q8
        if(wd < (uint16_t)(along >> 2)) continue;               // a wall is in the way

        cand[nc]  = i;
        candD[nc] = (uint16_t)along;
        nc++;
    }

    while(n < maxN && nc > 0)
    {
        k = 0;
        for(i = 1; i < nc; i++)
            if(candD[i] < candD[k]) k = i;
        out[n++] = cand[k];
        nc--;
        cand[k]  = cand[nc];
        candD[k] = candD[nc];
    }
    return n;
}


static bool CastTome(void)
{
    uint16_t idx[3], n, i;
    uint16_t dmg = ScaledDmg(3);

    n = AcquireTargets(3, idx);
    if(n == 0) { rc_Sfx(&sfx_menu_bump); return false; }

    for(i = 0; i < n; i++)
    {
        Enemy *e = &rc_en[idx[i]];

        rc_AddSpark(e->x, e->y, 6, 8, PT_PUFF_ARCANE, 8);
        DamageEnemy(e, dmg, 0, 0);
    }
    Buzzer_PlaySfx(&sfx_staff_prism);
    return true;
}


static void CastWarp(void)
{
    int16_t c = COS(rc_ang);
    int16_t s = SIN(rc_ang);
    int16_t nx, ny, i;

    for(i = 0; i < 24; i++)                     // up to 24 * 128 = 3 tiles
    {
        nx = rc_px + (int16_t)(((int32_t)c * 128L) >> 14);
        ny = rc_py + (int16_t)(((int32_t)s * 128L) >> 14);
        if(Blocked(nx, ny, RC_PLAYER_R)) break;
        rc_px = nx;
        rc_py = ny;
    }

    if(rc_invuln < 20) rc_invuln = 20;
    rc_stepAcc   = 0;
    rc_viewDirty = 2;
    Buzzer_PlaySfx(&sfx_staff_storm);
}


static void CastAegis(void)
{
    uint16_t i;

    rc_aegis = 150;
    rc_hud  |= HUD_HINT;

    for(i = 0; i < RC_MAX_ENEMIES; i++)         // shockwave
    {
        Enemy  *e = &rc_en[i];
        int16_t dx, dy, d, nx, ny;

        if(!e->alive) continue;
        dx = e->x - rc_px;
        dy = e->y - rc_py;
        d  = Dist10(dx, dy);
        if(d >= 2000 || d <= 0) continue;

        nx = e->x + (int16_t)(((int32_t)dx * 600L) / d);
        ny = e->y + (int16_t)(((int32_t)dy * 600L) / d);
        if(!Blocked(nx, e->y, 230)) e->x = nx;
        if(!Blocked(e->x, ny, 230)) e->y = ny;
        e->slow = 60;
    }
    rc_Sfx(&sfx_menu_select);
}


// Returns true if the item was used (so its cooldown starts).
static bool UseItem(uint16_t it)
{
    switch(it)
    {
        case IT_FIRE:
        case IT_FROST:
        case IT_VENOM:
            return ThrowFlask(it);                      // IT_ order == PK_ order

        case IT_ELIXIR:
            if(rc_hp >= rc_maxHp) { rc_Sfx(&sfx_menu_bump); return false; }
            rc_hp += 2;
            if(rc_hp > rc_maxHp) rc_hp = rc_maxHp;
            rc_hud |= HUD_HEARTS;
            rc_Sfx(&sfx_powerup);
            return true;

        case IT_HASTE:
            rc_haste = 300;
            rc_hud  |= HUD_HINT;
            rc_Sfx(&sfx_powerup);
            return true;

        case IT_TOME:
            return CastTome();

        case IT_WARP:
            CastWarp();
            return true;

        default:                                        // IT_AEGIS
            CastAegis();
            return true;
    }
}


void rc_UseEquipped(void)
{
    uint16_t slot = rc_equip;
    uint16_t it;
    uint16_t cost = rc_SlotMana(slot);

    if(rc_nullify) cost = (uint16_t)(cost * 2u);          // magic weakened
    if(rc_cd[slot]) return;

    if(rc_mana < cost)                                   // not enough mana
    {
        rc_cdMax[slot] = 10;
        rc_cd[slot]    = 10;                             // retry delay (holding U won't spam)
        rc_manaFlash   = 12;
        rc_Sfx(&sfx_menu_bump);
        return;
    }

    if(slot < NUM_STAFF)
    {
        Fire();
        rc_mana -= cost;
        return;
    }

    it = slot - NUM_STAFF;
    if(UseItem(it))
    {
        rc_mana       -= cost;                           // only paid if the item was used
        rc_cdMax[slot] = rc_kItem[it].cooldown;
        rc_cd[slot]    = rc_kItem[it].cooldown;
    }
    else
        rc_cd[slot] = 10;                                // brief retry delay
    rc_viewDirty = 2;
}


//-----------------------------------------------------------------------------
// Spawning
//-----------------------------------------------------------------------------
#define RAND(n)   ((uint16_t)(Rand16() % (uint16_t)(n)))

Enemy *rc_SpawnEnemy(uint16_t type, int16_t x, int16_t y)
{
    uint16_t i;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        Enemy *e = &rc_en[i];

        if(!e->alive)
        {
            int16_t hp = rc_kEnemy[type].hp;

            if(RC_IS_MINI(type))                        // mini-bosses grow with the round
                hp = (int16_t)(((int32_t)hp * (12 + (int16_t)rc_level)) / 12);
            else if(type == ET_DRAGON)                  // each Dragon is tougher than the last
                hp = (int16_t)(hp + 100 * (int16_t)rc_dragonKills);
            else                                        // later rounds are tougher
                hp = (int16_t)(((int32_t)hp * (8 + (int16_t)rc_level)) / 8);

            e->x = x;       e->y = y;
            e->hp = hp;     e->mhp = hp;
            e->type = type;
            e->flash = 0;   e->slow = 0;
            e->freeze = 0;  e->burn = 0;
            e->aux = 0;     e->aux2 = 0;
            e->st = 0;      e->an = 0;
            e->cnt = 0;     e->sum = 0;
            e->tx = 0;      e->ty = 0;
            e->tm = (type == ET_BAT) ? 0u : (uint16_t)(60u + RAND(120));   // first special move not at once
            e->alive = 1;
            rc_alive++;
            rc_hud |= HUD_LEFT;
            return e;
        }
    }
    return NULL;
}


uint16_t rc_CountType(uint16_t type)
{
    uint16_t i, n = 0;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
        if(rc_en[i].alive && rc_en[i].type == type) n++;
    return n;
}


// Enemies that must die before the wave counts as cleared. Summons, mini-bosses and the
// Dragon do not count (a mini-boss does not hold the next round back).
uint16_t rc_CountRegular(void)
{
    uint16_t i, n = 0;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        const Enemy *e = &rc_en[i];

        if(e->alive && !e->sum && !RC_IS_MINI(e->type) && e->type != ET_DRAGON &&
           !(e->type == ET_MIMIC && e->st == 0u)) n++;
    }
    return n;
}


// First marker in an UNLOCKED section that is not right on top of the player.
static bool PickMarker(bool arenaOnly, int16_t *x, int16_t *y)
{
    uint16_t tries, idx;

    for(tries = 0; tries < rc_spCount; tries++)
    {
        idx = rc_spawnIdx;
        rc_spawnIdx = (rc_spawnIdx + 1u) % rc_spCount;
        if(!rc_secOpen[rc_spSec[idx]]) continue;
        if(rc_spSec[idx] == 6u) continue;                  // the Den marker is only for the Dragon
        (void)arenaOnly;
        if(Dist10(rc_spX[idx] - rc_px, rc_spY[idx] - rc_py) > SPAWN_MIN_DIST)
        {
            *x = rc_spX[idx];
            *y = rc_spY[idx];
            return true;
        }
    }
    return false;
}


// Weighted pick for the regular wave (see rc_kSpawn).
static uint16_t PickType(void)
{
    uint16_t w[NUM_SPAWN], total = 0, i, r, wt, cap;

    for(i = 0; i < NUM_SPAWN; i++)
    {
        const SpawnDef *sd = &rc_kSpawn[i];

        w[i] = 0;
        if(rc_level < sd->unlock) continue;
        wt = (uint16_t)(sd->w0 + sd->wStep * (rc_level - sd->unlock));
        if(wt > sd->wMax) wt = sd->wMax;
        if(sd->cap < 99u)
        {
            cap = (uint16_t)(1u + (rc_level - sd->unlock) / 6u);
            if(cap > sd->cap) cap = sd->cap;
            if(rc_CountType(sd->type) >= cap) continue;
        }
        w[i]   = wt;
        total += wt;
    }
    if(total == 0u) return ET_GOBLIN;
    r = RAND(total);
    for(i = 0; i < NUM_SPAWN; i++)
    {
        if(r < w[i]) return rc_kSpawn[i].type;
        r -= w[i];
    }
    return ET_GOBLIN;
}


// A random mini-boss, never the same one twice in a row.
static uint16_t PickMini(void)
{
    uint16_t k = RAND(RC_NUM_MINI);

    if(rc_kMini[k] == rc_lastMini) k = (uint16_t)((k + 1u) % RC_NUM_MINI);
    rc_lastMini = rc_kMini[k];
    return rc_kMini[k];
}


void rc_TrySpawn(void)
{
    int16_t x, y;

    if(rc_spawnTimer) { rc_spawnTimer--; return; }
    if(rc_spCount == 0 || rc_lv.treasure || rc_denState == DEN_FIGHT) return;

    // The mini-boss for this round walks in once the wave is half done.
    if(rc_miniPending && !rc_lv.boss && rc_toSpawn <= rc_lv.total / 2u)
    {
        if(!PickMarker(false, &x, &y)) { rc_spawnTimer = 20; return; }
        {
            uint16_t mt = PickMini();

            if(rc_SpawnEnemy(mt, x, y) != NULL)
            {
                rc_miniAlive++;
                rc_ApplyTheme(rc_ThemeOfMini(mt));          // the walls take on the boss's look
                rc_Sfx(&sfx_level_up);
            }
        }
        rc_miniPending = 0;
        rc_spawnTimer  = 30;
        return;
    }

    if(!rc_toSpawn) return;
    if(rc_CountRegular() >= rc_lv.maxAlive) return;
    if(!PickMarker(false, &x, &y)) { rc_spawnTimer = 20; return; }
    rc_SpawnEnemy(PickType(), x, y);
    rc_toSpawn--;
    rc_spawnTimer = rc_lv.gap;
}


// Treasure round: one chest in an open room, and 1 time in 4 it is a Mimic.
void rc_StartTreasure(void)
{
    int16_t x, y;
    Obj    *o;

    if(!PickMarker(false, &x, &y))
    {
        x = rc_spX[0];
        y = rc_spY[0];
    }
    rc_chestTimer = 900;                            // 30 s, then the chest is gone
    if(RAND(4) == 0)
    {
        (void)rc_SpawnEnemy(ET_MIMIC, x, y);
        return;
    }
    o = rc_NewObj(OB_CHEST);
    if(o == NULL) { rc_gold += 50u; rc_chestTimer = 0; return; }
    o->x = x;
    o->y = y;
}


//-----------------------------------------------------------------------------
// Hazards shared by several enemies
//-----------------------------------------------------------------------------
// A red ring on the floor; after `life` frames it becomes a hazard of kind `area`
// that lasts areaLife frames (areaLife 0 = just the warning ring).
void rc_MakeWarn(int16_t x, int16_t y, int16_t r, uint16_t life, uint16_t area, uint16_t areaLife)
{
    Obj *o = rc_NewObj(OB_WARN);

    if(o == NULL) return;
    o->x    = x;
    o->y    = y;
    o->r    = r;
    o->life = life;
    o->aux  = area;
    o->vx   = (int16_t)areaLife;
}


// Expanding shockwave: outruns nobody who keeps moving away, hurts once when it crosses you.
void rc_MakeWave(int16_t x, int16_t y, int16_t speed, int16_t maxR, uint16_t flavour)
{
    Obj *o = rc_NewObj(OB_WAVE);

    if(o == NULL) return;
    o->x   = x;
    o->y   = y;
    o->r   = 200;
    o->vx  = speed;
    o->vy  = maxR;
    o->aux = flavour;
    o->sc  = 0;                                     // 1 = already hit the player
    rc_Sfx(&sfx_explosion);
}


// Bomb Imp blast: hurts the player and every enemy close by, and leaves scorched ground.
void rc_Explode(int16_t x, int16_t y)
{
    uint16_t i;
    Obj     *o;

    rc_AddSpark(x, y, 4, 20, PT_PUFF_FIRE, 12);
    rc_AddSpark((int16_t)(x + 300), y, 6, 14, PT_PUFF_FIRE, 10);
    rc_AddSpark((int16_t)(x - 300), y, 6, 14, PT_PUFF_FIRE, 10);
    if(Dist10((int16_t)(rc_px - x), (int16_t)(rc_py - y)) < 1300) rc_HurtPlayer();
    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        Enemy *e = &rc_en[i];

        if(!e->alive) continue;
        if(Dist10((int16_t)(e->x - x), (int16_t)(e->y - y)) < 1300)
            rc_DamageEnemyEx(e, 4, 0, 0, true);
    }
    o = rc_NewObj(OB_AREA);
    if(o != NULL) { o->x = x; o->y = y; o->r = 800; o->life = 45; o->aux = AR_BLAST; }
    rc_Sfx(&sfx_explosion);
}


//-----------------------------------------------------------------------------
// Path-finding: a breadth-first "steps to the player" map over the 16 x 16 grid.
// Rebuilt whenever the player changes tile or a door opens (a few hundred cells).
// Enemies that can see you walk straight at you; otherwise they follow the map.
//-----------------------------------------------------------------------------
const int16_t rc_kNbDx[4] = { 1, -1, 0, 0 };

const int16_t rc_kNbDy[4] = { 0, 0, 1, -1 };


//-----------------------------------------------------------------------------
// Hallway events: buying door 3 or 6 reveals a hallway; something waits in its alcove.
//-----------------------------------------------------------------------------
void rc_HallwayEvent(uint16_t door)
{
    uint16_t idx = (door == 6u) ? 0u : 1u;
    uint16_t r   = (uint16_t)(Rand16() % 100u);
    Obj     *o;

    if(rc_evX[idx] == 0) return;
    if(r < 28u)                                     // merchant
    {
        o = rc_NewObj(OB_MERCHANT);
        if(o != NULL) { o->x = rc_evX[idx]; o->y = rc_evY[idx]; }
    }
    else if(r < 86u && r >= 70u)                    // mimic: looks like a normal chest
    {
        (void)rc_SpawnEnemy(ET_MIMIC, rc_evX[idx], rc_evY[idx]);
    }
    else                                            // regular / cursed / poison-trap chest
    {
        o = rc_NewObj(OB_CHEST);
        if(o != NULL)
        {
            o->x   = rc_evX[idx];
            o->y   = rc_evY[idx];
            o->aux = (r < 56u) ? CH_REGULAR : (r < 70u) ? CH_CURSED : CH_POISON;
        }
    }
}
